package com.supermarkettracker.infrastructure.persistence.adapter;
import com.supermarkettracker.domain.model.*; import com.supermarkettracker.domain.model.enums.StatusAtivo; import com.supermarkettracker.domain.model.valueobject.Identificador; import com.supermarkettracker.domain.repository.EmpresaRepository; import com.supermarkettracker.infrastructure.persistence.mapper.EmpresaPersistenceMapper; import com.supermarkettracker.infrastructure.persistence.repository.EmpresaJpaRepository; import com.supermarkettracker.infrastructure.persistence.repository.EmpresaUsuarioJpaRepository; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class EmpresaRepositoryJpaAdapter implements EmpresaRepository { private final EmpresaJpaRepository jpa; private final EmpresaPersistenceMapper mapper; private final EmpresaUsuarioJpaRepository euJpa; public EmpresaRepositoryJpaAdapter(EmpresaJpaRepository jpa, EmpresaPersistenceMapper mapper, EmpresaUsuarioJpaRepository euJpa){this.jpa=jpa;this.mapper=mapper;this.euJpa=euJpa;} public Empresa salvar(Empresa e){return mapper.toDomain(jpa.save(mapper.toEntity(e)));} public Optional<Empresa> buscarPorId(Identificador id){return jpa.findById(id.valor()).map(mapper::toDomain);} public List<Empresa> listarPorUsuario(Identificador usuarioId) { List<Empresa> empresas = new ArrayList<>(); for (var eu : euJpa.findByUsuarioIdAndStatusOrderByCriadoEmDesc(usuarioId.valor(), StatusAtivo.ATIVO)) { jpa.findById(eu.empresaId).ifPresent(e -> empresas.add(mapper.toDomain(e))); } return empresas; } }
